ga5x(){return"\u062a\u064f\u0631\u0633\u0644 \u0635\u0648\u0631\u0629 \u0627\u0644\u0645\u0633\u062a\u0646\u062f \u0625\u0644\u0649 \u062e\u062f\u0645\u0629 \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a \u062e\u0627\u0631\u062c\u064a\u0629 \u0644\u0642\u0631\u0627\u0621\u062a\u0647\u0627. \u0644\u0627 \u064a\u064f\u0631\u0633\u0644 \u0645\u0639\u0647\u0627 \u0627\u0633\u0645\u0643 \u0648\u0644\u0627 \u0631\u0642\u0645\u0643 \u0627\u0644\u0635\u062d\u064a \u0648\u0644\u0627 \u0623\u064a \u0645\u0639\u0644\u0648\u0645\u0629 \u062a\u0639\u0631\u0651\u0641\u0643\u060c \u0648\u0644\u0627 \u0646\u0633\u062c\u0651\u0644 \u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0641\u064a \u0623\u064a \u0633\u062c\u0644 \u062a\u0634\u063a\u064a\u0644\u064a. \u0648\u0644\u0627 \u062a\u064f\u0636\u0627\u0641 \u0623\u064a \u0642\u064a\u0645\u0629 \u0625\u0644\u0649 \u0633\u062c\u0644\u0651\u0643 \u0642\u0628\u0644 \u0623\u0646 \u062a\u0624\u0643\u0651\u062f\u0647\u0627 \u0623\u0646\u062a."},
ga5w(){return"\u0641\u0647\u0645\u062a"},
gaey(){return"\u0642\u0631\u0623\u0646\u0627 \u0647\u0630\u0647 \u0627\u0644\u0643\u0644\u0645\u0629 \u0644\u0643\u0646 \u0644\u0627 \u0646\u0639\u0631\u0641\u0647\u0627 \u2014 \u0645\u0627\u0630\u0627 \u062a\u0639\u0646\u064a\u061f"},
gaer(){return"\u0625\u064a\u062c\u0627\u0628\u064a"},
gaeq(){return"\u0633\u0644\u0628\u064a"},
gaeH(){return"\u0623\u0636\u0641 \u0627\u0644\u0648\u062d\u062f\u0629 \u0627\u0644\u0645\u0637\u0628\u0648\u0639\u0629 \u0641\u064a \u0627\u0644\u0648\u0631\u0642\u0629"},
gai0(){return"\u0627\u0644\u0642\u064a\u0645 \u0627\u0644\u062a\u064a \u062a\u0624\u0643\u0651\u062f\u0647\u0627 \u0645\u0646 \u062a\u0642\u0631\u064a\u0631 \u0645\u0631\u0641\u0648\u0639 \u062a\u0638\u0647\u0631 \u0647\u0646\u0627"},
gSG(){return"\u062a\u0639\u0630\u0651\u0631 \u0639\u0631\u0636 \u0647\u0630\u0627 \u0627\u0644\u0645\u0633\u062a\u0646\u062f"},
gamT(){return"\u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629"},
acB(a,b){return"\u0635\u0641\u062d\u0629 "+a+" \u0645\u0646 "+b},
gaek(){return"\u0644\u0627 \u064a\u0645\u0643\u0646\u0646\u0627 \u062a\u062d\u062f\u064a\u062f \u0645\u0648\u0636\u0639 \u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0645\u0629 \u0641\u064a \u0627\u0644\u0635\u0641\u062d\u0629 \u2014 \u062a\u062d\u0642\u0651\u0642 \u0645\u0646\u0647\u0627 \u0628\u0646\u0641\u0633\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0646\u062f"},
Tf(a){return""+a+" \u062a\u0642\u0631\u064a\u0631 \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0645\u0631\u0627\u062c\u0639\u062a\u0643"},
gTe(){return"\u0631\u0627\u062c\u0639\u0647\u0627 \u0627\u0644\u0622\u0646"},
gacC(){return"\u0627\u0644\u0635\u0641\u062d\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629"},
