gX9(){return"\u0626\u06d5\u0645 \u06a9\u06d5\u0633\u06d5 \u062f\u06d5\u0646\u0627\u0633\u0645"},
ganc(){return"\u0626\u06d5\u0631\u06a9\u06d5\u06a9\u06d5 \u062f\u06d5\u06af\u06d5\u0695\u06ce\u062a\u06d5\u0648\u06d5 \u0695\u06cc\u0632\u06d5\u06a9\u06d5\u060c \u0647\u06c6\u06a9\u0627\u0631\u06d5\u06a9\u06d5 \u062a\u06c6\u0645\u0627\u0631 \u062f\u06d5\u06a9\u0631\u06ce\u062a\u060c \u0648 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0647\u06cc\u0686 \u0626\u06d5\u0631\u06a9\u06ce\u06a9\u06cc \u0626\u06d5\u0645 \u0646\u06d5\u062e\u06c6\u0634\u06d5 \u062c\u0627\u0631\u06ce\u06a9\u06cc \u062a\u0631 \u067e\u06ce\u062a \u0646\u0627\u062f\u0631\u06ce\u062a."},
