gakM(){return"\u0646\u06d5\u062e\u06c6\u0634\u06d5\u06a9\u06d5"},
gakX(){return"\u062f\u06d5\u0631\u0645\u0627\u0646\u062e\u0627\u0646\u06d5 \u0648\u06d5\u0633\u0641\u06d5\u06a9\u0627\u0646 \u0648 \u0647\u06d5\u0633\u062a\u06cc\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u0648 \u0645\u06ce\u0698\u0648\u0648\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06cc \u062f\u06d5\u0628\u06cc\u0646\u06ce\u062a \u2014 \u0646\u06d5 \u0633\u06d5\u0631\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646 \u0648 \u0646\u06d5 \u067e\u0634\u06a9\u0646\u06cc\u0646\u06d5\u06a9\u0627\u0646 \u0648 \u0646\u06d5 \u0628\u06d5\u06b5\u06af\u06d5\u06a9\u0627\u0646."},
gW1(){return"\u0648\u06d5\u0633\u0641\u06d5 \u0686\u0627\u0644\u0627\u06a9\u06d5\u06a9\u0627\u0646"},
gakJ(){return"\u0647\u06cc\u0686 \u0648\u06d5\u0633\u0641\u06d5\u06cc\u06d5\u06a9\u06cc \u0686\u0627\u0644\u0627\u06a9 \u0646\u06cc\u06cc\u06d5 \u0628\u06c6 \u0626\u06d5\u0645 \u0646\u06d5\u062e\u06c6\u0634\u06d5."},
gakL(){return"\u0648\u06d5\u0633\u0641\u06d5 \u067e\u06ce\u0634\u0648\u0648\u06d5\u06a9\u0627\u0646"},
gakh(){return"\u067e\u0627\u0634\u062e\u0627\u0646\u06cc \u0633\u06d5\u0644\u0627\u0645\u06d5\u062a\u06cc"},
gakf(){return"\u0644\u06cc\u0633\u062a\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u0648 \u062f\u06d5\u0631\u0645\u0627\u0646\u06d5 \u0628\u06d5\u0631\u062f\u06d5\u0648\u0627\u0645\u06d5\u06a9\u0627\u0646 \u2014 \u0628\u06c6 \u062d\u0648\u06a9\u0645\u06cc \u062e\u06c6\u062a \u0644\u06d5\u0633\u06d5\u0631 \u06a9\u0627\u0631\u0644\u06ce\u06a9\u06d5\u06a9\u0627\u0646."},
