gakH(){return"\u0628\u06d5 \u062a\u06d5\u0648\u0627\u0648\u06cc \u062f\u0631\u0627\u0648\u06d5"},
gako(){return"\u0628\u0695\u06cc \u062f\u0631\u0627\u0648"},
