ga9n(){return"\u0646\u0645\u0648\u0648\u0646\u06d5: \u06a9\u06d5\u0645\u0626\u06d5\u0646\u062f\u0627\u0645\u06cc \u06af\u0648\u0631\u0686\u06cc\u0644\u06d5 \u2014 \u062f\u0648\u0648\u0631\u06cc \u0644\u06d5 NSAIDs"},
gXM(){return"\u0648\u06ce\u0646\u06d5\u06cc\u06d5\u06a9 \u0628\u06d5 \u06a9\u0627\u0645\u06ce\u0631\u0627 \u0628\u06af\u0631\u06d5"},
gXL(){return"\u0695\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0648\u06ce\u0646\u06d5\u06cc \u06a9\u0627\u063a\u06d5\u0632\u06d5\u06a9\u06d5 \u0628\u06af\u0631\u06d5 \u2014 \u0644\u06d5\u0633\u06d5\u0631 \u06a9\u06c6\u0645\u067e\u06cc\u0648\u062a\u06d5\u0631 \u0644\u06d5\u0648\u0627\u0646\u06d5\u06cc\u06d5 \u0648\u06ce\u0628\u06af\u06d5\u0695 \u067e\u06d5\u0646\u062c\u06d5\u0631\u06d5\u06cc \u0641\u0627\u06cc\u0644 \u0628\u06a9\u0627\u062a\u06d5\u0648\u06d5 \u0644\u06d5 \u062c\u06cc\u0627\u062a\u06cc \u06a9\u0627\u0645\u06ce\u0631\u0627"},
ga6e(){return"\u062f\u0627\u0645\u06d5\u0632\u0631\u0627\u0648\u06d5\u06cc\u06d5\u06a9\u06cc \u062a\u06d5\u0646\u062f\u0631\u0648\u0633\u062a\u06cc\u061f \u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u062f\u0627\u0645\u06d5\u0632\u0631\u0627\u0648\u06d5\u06a9\u06d5 \u062a\u06c6\u0645\u0627\u0631 \u0628\u06a9\u06d5"},
ga6f(){return"\u0646\u06d5\u062e\u06c6\u0634\u062e\u0627\u0646\u06d5 \u06cc\u0627\u0646 \u062a\u0627\u0642\u06cc\u06af\u06d5 \u06cc\u0627\u0646 \u062f\u06d5\u0631\u0645\u0627\u0646\u062e\u0627\u0646\u06d5 \u2014 \u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u062f\u0627\u0645\u06d5\u0632\u0631\u0627\u0648\u06d5 \u062c\u06cc\u0627\u0648\u0627\u0632\u06d5 \u0644\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06cc \u062a\u06d5\u0646\u062f\u0631\u0648\u0633\u062a\u06cc \u06a9\u06d5\u0633\u06cc \u062e\u06c6\u062a."},
