ga6g(){return"\u062f\u0627\u0645\u06d5\u0632\u0631\u0627\u0648\u06d5 \u0646\u06d5\u062e\u06c6\u0634 \u0646\u06cc\u06cc\u06d5: \u0646\u06d5 \u0698\u0645\u0627\u0631\u06d5\u06cc \u062a\u06d5\u0646\u062f\u0631\u0648\u0633\u062a\u06cc \u0647\u06d5\u06cc\u06d5 \u0648 \u0646\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06cc \u067e\u0632\u06cc\u0634\u06a9\u06cc. \u062a\u06c6\u0645\u0627\u0631\u06cc \u062a\u06d5\u0646\u062f\u0631\u0648\u0633\u062a\u06cc \u06a9\u06d5\u0633\u06cc\u062a \u0644\u06d5\u0633\u06d5\u0631 \u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u06a9\u06d5\u0633\u06cc \u062e\u06c6\u062a \u062f\u06d5\u0645\u06ce\u0646\u06ce\u062a\u06d5\u0648\u06d5 \u0628\u06d5 \u0698\u0645\u0627\u0631\u06d5\u06cc \u0645\u06c6\u0628\u0627\u06cc\u0644\u06cc \u062e\u06c6\u062a."},
ga6b(){return"\u0646\u0627\u0648\u06cc \u062f\u0627\u0645\u06d5\u0632\u0631\u0627\u0648\u06d5"},
ga6a(){return"\u0646\u06d5\u062e\u06c6\u0634\u062e\u0627\u0646\u06d5\u06cc \u0647\u06cc\u0648\u0627 \xb7 \u062a\u0627\u0642\u06cc\u06af\u06d5\u06cc \u0646\u0648\u0648\u0631 \xb7 \u062f\u06d5\u0631\u0645\u0627\u0646\u062e\u0627\u0646\u06d5\u06cc \u0634\u06cc\u0641\u0627"},
